import numpy as np
from solver import Solver

def test():
    solver = Solver()
    A = np.array([[5+1j, 4+0j], [1+0j, 2+1j]], dtype=complex)
    problem = {"matrix": A}

    solution = solver.solve(problem)
    X = np.array(solution["sqrtm"]["X"])

    print("Reconstructed A:")
    print(X @ X)
    print("Original A:")
    print(A)
    print("Match:", np.allclose(X @ X, A))

test()
